# Let's find where the actual graph edges are - they're likely after the examples
# Look for lines with "->" that are not in the first example section

# First, let's find all lines with "->" and see where they cluster
edge_lines = []
for i, line in enumerate(lines):
    if "->" in line and not line.startswith("Example") and not line.startswith("Operation"):
        edge_lines.append((i, line.strip()))

print(f"Total lines with '->': {len(edge_lines)}")
print("First 10 edge lines:")
for i, (idx, line) in enumerate(edge_lines[:10]):
    print(f"  Line {idx}: {line}")
print("\nLast 10 edge lines:")
for i, (idx, line) in enumerate(edge_lines[-10:]):
    print(f"  Line {idx}: {line}")

# Find where there's a big gap (end of examples, start of real data)
print("\nLooking for gaps in edge line indices...")
for i in range(1, min(50, len(edge_lines))):
    gap = edge_lines[i][0] - edge_lines[i-1][0]
    if gap > 10:
        print(f"Big gap at index {i}: line {edge_lines[i-1][0]} to {edge_lines[i][0]} (gap of {gap})")
